import json

ALLOWED = {"배송 지연", "파손", "오배송", "환불 문의", "기타"}
PROMPT = """너는 고객 문의 분류기다. 아래 문의를 다음 중 하나로만 분류하라: {labels}.
JSON 한 줄로만 답하라: {{"label": "...", "reason": "20자 이내"}}
문의: {text}"""

def parse(raw):
    try:
        obj = json.loads(raw)
    except json.JSONDecodeError:
        return None, "JSON 아님"
    if obj.get("label") not in ALLOWED:
        return None, "목록 밖 라벨: " + str(obj.get("label"))
    return obj["label"], "ok"

print(PROMPT.format(labels=", ".join(sorted(ALLOWED)), text="상자가 찌그러져 왔어요")[:60] + "...")
# 모델 응답이라고 치고 넣어 본 가짜 답 네 개
fake = ['{"label": "파손", "reason": "상자 찌그러짐"}',
        '분류: 파손',
        '{"label": "포장 불량", "reason": "상자"}',
        '{"label": "배송 지연", "reason": "도착 늦음"}']
for r in fake:
    print(parse(r))
